import {afterAll, beforeAll, beforeEach, describe, expect, it} from "vitest";
import {TestEnvironment, waitForFunctions} from "./support/testEnvironment.js";

describe("backfillMultiCollectionSubcollections", () => {
  const env = new TestEnvironment({
    dotenvPath: "test/integration/fixtures/multi-collection-subcollections.env",
    outputAllEmulatorLogs: true,
  });

  const parentCollectionPath1 = "users";
  const parentCollectionPath2 = "stores";
  const childFieldName1 = "books";
  const childFieldName2 = "products";
  const unrelatedCollectionPath = "unrelatedCollectionToNotBackfill";

  const typesenseCollectionNames = (): string[] => Object.values(env.collections).map((c) => c.typesenseCollection);

  beforeAll(async () => {
    await env.setup();
  });

  afterAll(async () => {
    await env.teardown();
  });

  beforeEach(async () => {
    // Clear Firestore collections - need to clear parent collections to remove subcollections
    for (const collectionPath of Object.keys(env.collections)) {
      // For subcollections, we need to clear the parent collection
      const parentPath = collectionPath.split("/")[0] ?? collectionPath; // e.g., "users" from "users/{userId}/books"
      await env.firestore.recursiveDelete(env.firestore.collection(parentPath));
    }

    await env.firestore.recursiveDelete(env.firestore.collection(unrelatedCollectionPath));

    await waitForFunctions(3000);

    // Clear and recreate Typesense collections
    await env.recreateTypesenseCollections(typesenseCollectionNames());

    // Wait for Typesense collections to be ready
    await waitForFunctions(1000);
  });

  describe("when firestore_collections is not specified", () => {
    it("backfills existing Firestore data in all subcollections to Typesense when `trigger: true` is set", async () => {
      const parentDocData1 = {
        name: "John Doe",
        email: "john@example.com",
      };

      const parentDocData2 = {
        name: "Store ABC",
        location: "NYC",
      };

      const subDocData1 = {
        title: "Book Title",
        author: "Author A",
        rating: 4.5,
      };

      const subDocData2 = {
        name: "Product XYZ",
        price: 99.99,
        category: "electronics",
      };

      // Create parent documents in Firestore
      const parentDocRef1 = await env.firestore.collection(parentCollectionPath1).add(parentDocData1);
      const parentDocRef2 = await env.firestore.collection(parentCollectionPath2).add(parentDocData2);

      // Create subcollections with documents under the parent documents
      const subDocRef1 = await parentDocRef1.collection(childFieldName1).add(subDocData1);
      const subDocRef2 = await parentDocRef2.collection(childFieldName2).add(subDocData2);

      // Wait for firestore cloud function to write to Typesense
      await waitForFunctions(2000);

      // Delete Typesense collections to test backfill
      await env.recreateTypesenseCollections(typesenseCollectionNames());

      await env.triggerBackfill({trigger: true});
      await waitForFunctions(2000);

      expect(await env.exportDocuments("user_books")).toStrictEqual([
        {
          id: subDocRef1.id,
          title: subDocData1.title,
          author: subDocData1.author,
          rating: subDocData1.rating,
          userId: parentDocRef1.id,
        },
      ]);

      expect(await env.exportDocuments("store_products")).toStrictEqual([
        {
          id: subDocRef2.id,
          name: subDocData2.name,
          price: subDocData2.price,
          category: subDocData2.category,
          storeId: parentDocRef2.id,
        },
      ]);
    });
  });

  describe("when firestore_collections is specified", () => {
    describe("when firestore_collections includes configured subcollections", () => {
      it("backfills existing Firestore data in specified subcollections to Typesense when `trigger: true` is set", async () => {
        const parentDocData1 = {
          name: "John Doe",
          email: "john@example.com",
        };

        const parentDocData2 = {
          name: "Store ABC",
          location: "NYC",
        };

        const subDocData1 = {
          title: "Book Title",
          author: "Author A",
          rating: 4.5,
        };

        const subDocData2 = {
          name: "Product XYZ",
          price: 99.99,
          category: "electronics",
        };

        // Create parent documents in Firestore
        const parentDocRef1 = await env.firestore.collection(parentCollectionPath1).add(parentDocData1);
        const parentDocRef2 = await env.firestore.collection(parentCollectionPath2).add(parentDocData2);

        // Create subcollections with documents under the parent documents
        const subDocRef1 = await parentDocRef1.collection(childFieldName1).add(subDocData1);
        await parentDocRef2.collection(childFieldName2).add(subDocData2);

        // Wait for firestore cloud function to write to Typesense
        await waitForFunctions(2000);

        // Delete Typesense collections to test backfill
        await env.recreateTypesenseCollections(typesenseCollectionNames());

        // Trigger backfill for specific subcollections only
        await env.triggerBackfill({
          trigger: true,
          firestore_collections: ["users/{userId}/books"],
        });
        await waitForFunctions(2000);

        // Check that only specified subcollections were backfilled
        expect(await env.exportDocuments("user_books")).toStrictEqual([
          {
            id: subDocRef1.id,
            title: subDocData1.title,
            author: subDocData1.author,
            rating: subDocData1.rating,
            userId: parentDocRef1.id,
          },
        ]);

        // Check that store_products collection was NOT backfilled
        expect(await env.exportDocuments("store_products")).toEqual([]);
      });
    });

    describe("when firestore_collections does not include any configured subcollections", () => {
      it("does not backfill existing Firestore data when `trigger: true` is set", async () => {
        const parentDocData1 = {
          name: "John Doe",
          email: "john@example.com",
        };

        const parentDocData2 = {
          name: "Store ABC",
          location: "NYC",
        };

        const subDocData1 = {
          title: "Book Title",
          author: "Author A",
          rating: 4.5,
        };

        const subDocData2 = {
          name: "Product XYZ",
          price: 99.99,
          category: "electronics",
        };

        // Create parent documents in Firestore
        const parentDocRef1 = await env.firestore.collection(parentCollectionPath1).add(parentDocData1);
        const parentDocRef2 = await env.firestore.collection(parentCollectionPath2).add(parentDocData2);

        // Create subcollections with documents under the parent documents
        await parentDocRef1.collection(childFieldName1).add(subDocData1);
        await parentDocRef2.collection(childFieldName2).add(subDocData2);

        // Wait for firestore cloud function to write to Typesense
        await waitForFunctions(2000);

        // Delete Typesense collections to test backfill
        await env.recreateTypesenseCollections(typesenseCollectionNames());

        // Trigger backfill for non-configured subcollections
        await env.triggerBackfill({
          trigger: true,
          firestore_collections: ["some/other/collection", "another/unrelated/collection"],
        });
        await waitForFunctions(2000);

        // Check that no collections were backfilled
        for (const collectionName of typesenseCollectionNames()) {
          expect(await env.exportDocuments(collectionName)).toEqual([]);
        }
      });
    });
  });

  describe("Backfill subcollections with field filtering", () => {
    it("respects collection-specific field filtering during backfill", async () => {
      const parentDocData1 = {
        name: "John Doe",
        email: "john@example.com",
      };

      const parentDocData2 = {
        name: "Store ABC",
        location: "NYC",
      };

      const subDocData1 = {
        title: "Book Title",
        author: "Author A",
        rating: 4.5,
        isbn: "123456789", // This should be filtered out (not in fields list)
        publisher: "Publisher XYZ", // This should be filtered out (not in fields list)
      };

      const subDocData2 = {
        name: "Product XYZ",
        price: 99.99,
        category: "electronics",
        sku: "SKU123", // This should be filtered out (not in fields list)
        brand: "Brand ABC", // This should be filtered out (not in fields list)
      };

      // Create parent documents in Firestore
      const parentDocRef1 = await env.firestore.collection(parentCollectionPath1).add(parentDocData1);
      const parentDocRef2 = await env.firestore.collection(parentCollectionPath2).add(parentDocData2);

      // Create subcollections with documents under the parent documents
      const subDocRef1 = await parentDocRef1.collection(childFieldName1).add(subDocData1);
      const subDocRef2 = await parentDocRef2.collection(childFieldName2).add(subDocData2);

      // Wait for firestore cloud function to write to Typesense
      await waitForFunctions(2000);

      // Delete Typesense collections to test backfill
      await env.recreateTypesenseCollections(typesenseCollectionNames());

      await env.triggerBackfill({trigger: true});
      await waitForFunctions(5000);

      // Check that only specified fields were backfilled
      const userBooksDocs = await env.exportDocuments("user_books");
      expect(userBooksDocs.length).toBe(1);
      const [userBook] = userBooksDocs;
      expect(userBook).toStrictEqual({
        id: subDocRef1.id,
        title: subDocData1.title,
        author: subDocData1.author,
        rating: subDocData1.rating,
        userId: parentDocRef1.id,
        // isbn and publisher should NOT be present
      });
      expect(userBook).not.toHaveProperty("isbn");
      expect(userBook).not.toHaveProperty("publisher");

      const storeProductsDocs = await env.exportDocuments("store_products");
      expect(storeProductsDocs.length).toBe(1);
      const [storeProduct] = storeProductsDocs;
      expect(storeProduct).toStrictEqual({
        id: subDocRef2.id,
        name: subDocData2.name,
        price: subDocData2.price,
        category: subDocData2.category,
        storeId: parentDocRef2.id,
        // sku and brand should NOT be present
      });
      expect(storeProduct).not.toHaveProperty("sku");
      expect(storeProduct).not.toHaveProperty("brand");
    });
  });

  describe("Backfill subcollections", () => {
    it("Ensure backfill doesn't backfill unrelated collections", async () => {
      const parentDocData1 = {
        name: "John Doe",
        email: "john@example.com",
      };

      const parentDocData2 = {
        name: "Store ABC",
        location: "NYC",
      };

      const subDocData1 = {
        title: "Book Title",
        author: "Author A",
        rating: 4.5,
      };

      const subDocData2 = {
        name: "Product XYZ",
        price: 99.99,
        category: "electronics",
      };

      // Create parent documents in Firestore
      const parentDocRef1 = await env.firestore.collection(parentCollectionPath1).add(parentDocData1);
      const parentDocRef2 = await env.firestore.collection(parentCollectionPath2).add(parentDocData2);

      // Create subcollections with documents under the parent documents
      const subDocRef1 = await parentDocRef1.collection(childFieldName1).add(subDocData1);
      const subDocRef2 = await parentDocRef2.collection(childFieldName2).add(subDocData2);

      // Create an unrelated set of documents that should not be backfilled
      const unrelatedParentDocData = {
        name: "Unrelated Parent",
        type: "unrelated",
      };

      const unrelatedSubDocData = {
        title: "Unrelated Document",
        content: "This should not be backfilled",
      };

      // Create unrelated parent document in Firestore
      const unrelatedParentDocRef = await env.firestore.collection(unrelatedCollectionPath).add(unrelatedParentDocData);

      // Create a subcollection with document under the unrelated parent document
      await unrelatedParentDocRef.collection(childFieldName1).add(unrelatedSubDocData);

      // Wait for firestore cloud function to write to Typesense
      await waitForFunctions(2000);

      // Delete Typesense collections to test backfill
      await env.recreateTypesenseCollections(typesenseCollectionNames());

      // Trigger backfill for configured subcollections only
      await env.triggerBackfill({
        trigger: true,
        firestore_collections: ["users/{userId}/books", "stores/{storeId}/products"],
      });
      await waitForFunctions(2000);

      // Check that only configured subcollections were backfilled
      expect(await env.exportDocuments("user_books")).toStrictEqual([
        {
          id: subDocRef1.id,
          title: subDocData1.title,
          author: subDocData1.author,
          rating: subDocData1.rating,
          userId: parentDocRef1.id,
        },
      ]);

      expect(await env.exportDocuments("store_products")).toStrictEqual([
        {
          id: subDocRef2.id,
          name: subDocData2.name,
          price: subDocData2.price,
          category: subDocData2.category,
          storeId: parentDocRef2.id,
        },
      ]);
    });
  });
});

import {afterAll, beforeAll, beforeEach, describe, expect, it} from "vitest";
import {TestEnvironment, waitForFunctions} from "./support/testEnvironment.js";

describe("backfillMultiCollection", () => {
  const env = new TestEnvironment({
    dotenvPath: "test/integration/fixtures/multi-collection.env",
    outputAllEmulatorLogs: true,
  });

  const typesenseCollectionNames = (): string[] => Object.values(env.collections).map((c) => c.typesenseCollection);

  beforeAll(async () => {
    await env.setup();
  });

  afterAll(async () => {
    await env.teardown();
  });

  beforeEach(async () => {
    for (const collectionPath of Object.keys(env.collections)) {
      await env.firestore.recursiveDelete(env.firestore.collection(collectionPath));
    }

    await env.recreateTypesenseCollections(typesenseCollectionNames());
  });

  describe("when firestore_collections is not specified", () => {
    it("backfills existing Firestore data in all collections to Typesense when `trigger: true` is set", async () => {
      const userData = {
        name: "John Doe",
        email: "john@example.com",
        profile: {
          age: 30,
          location: "NYC",
        },
      };

      const productData = {
        title: "Sample Product",
        description: "A great product",
        nested_field: {
          tags: ["electronics", "gadget"],
          category: "tech",
        },
      };

      const customerData = {
        name: "Jane Smith",
        email: "jane@example.com",
        profile: {
          age: 25,
          location: "LA",
        },
      };

      const orderData = {
        title: "Order #123",
        description: "Customer order",
        nested_field: {
          items: ["item1", "item2"],
          status: "pending",
        },
      };

      const userDoc = await env.firestore.collection("users").add(userData);
      const productDoc = await env.firestore.collection("products").add(productData);
      const customerDoc = await env.firestore.collection("customers").add(customerData);
      const orderDoc = await env.firestore.collection("orders").add(orderData);

      await waitForFunctions(2000);

      await env.recreateTypesenseCollections(typesenseCollectionNames());

      await env.triggerBackfill({trigger: true});
      await waitForFunctions(5000);

      expect(await env.exportDocuments("users")).toStrictEqual([
        {
          id: userDoc.id,
          name: userData.name,
          email: userData.email,
          profile: userData.profile,
        },
      ]);

      expect(await env.exportDocuments("products")).toStrictEqual([
        {
          id: productDoc.id,
          title: productData.title,
          description: productData.description,
          "nested_field.tags": productData.nested_field.tags,
          "nested_field.category": productData.nested_field.category,
        },
      ]);

      expect(await env.exportDocuments("customers")).toStrictEqual([
        {
          id: customerDoc.id,
          name: customerData.name,
          email: customerData.email,
          profile: customerData.profile,
        },
      ]);

      expect(await env.exportDocuments("orders")).toStrictEqual([
        {
          id: orderDoc.id,
          title: orderData.title,
          description: orderData.description,
          "nested_field.items": orderData.nested_field.items,
          "nested_field.status": orderData.nested_field.status,
        },
      ]);
    });
  });

  describe("when firestore_collections is specified", () => {
    describe("when firestore_collections includes configured collections", () => {
      it("backfills existing Firestore data in specified collections to Typesense when `trigger: true` is set", async () => {
        const userData = {
          name: "John Doe",
          email: "john@example.com",
          profile: {
            age: 30,
            location: "NYC",
          },
        };

        const productData = {
          title: "Sample Product",
          description: "A great product",
          nested_field: {
            tags: ["electronics", "gadget"],
            category: "tech",
          },
        };

        const customerData = {
          name: "Jane Smith",
          email: "jane@example.com",
          profile: {
            age: 25,
            location: "LA",
          },
        };

        const userDoc = await env.firestore.collection("users").add(userData);
        const productDoc = await env.firestore.collection("products").add(productData);
        await env.firestore.collection("customers").add(customerData);

        await waitForFunctions(2000);

        await env.recreateTypesenseCollections(typesenseCollectionNames());

        await env.triggerBackfill({
          trigger: true,
          firestore_collections: ["users", "products"],
        });
        await waitForFunctions(2000);

        expect(await env.exportDocuments("users")).toStrictEqual([
          {
            id: userDoc.id,
            name: userData.name,
            email: userData.email,
            profile: userData.profile,
          },
        ]);

        expect(await env.exportDocuments("products")).toStrictEqual([
          {
            id: productDoc.id,
            title: productData.title,
            description: productData.description,
            "nested_field.tags": productData.nested_field.tags,
            "nested_field.category": productData.nested_field.category,
          },
        ]);

        expect(await env.exportDocuments("customers")).toEqual([]);
      });
    });

    describe("when firestore_collections does not include any configured collections", () => {
      it("does not backfill existing Firestore data when `trigger: true` is set", async () => {
        const userData = {
          name: "John Doe",
          email: "john@example.com",
          profile: {
            age: 30,
            location: "NYC",
          },
        };

        const productData = {
          title: "Sample Product",
          description: "A great product",
          nested_field: {
            tags: ["electronics", "gadget"],
            category: "tech",
          },
        };

        await env.firestore.collection("users").add(userData);
        await env.firestore.collection("products").add(productData);

        await waitForFunctions(2000);

        await env.recreateTypesenseCollections(typesenseCollectionNames());

        await env.triggerBackfill({
          trigger: true,
          firestore_collections: ["some/other/collection", "another/unrelated/collection"],
        });
        await waitForFunctions(5000);

        for (const collectionName of typesenseCollectionNames()) {
          expect(await env.exportDocuments(collectionName)).toEqual([]);
        }
      });
    });
  });

  describe("Backfill with field filtering", () => {
    it("respects collection-specific field filtering during backfill", async () => {
      const customerData = [
        {
          name: "John Doe",
          email: "john@example.com",
          age: 30, // this should be filtered out (not in fields list)
          phone: "123-456-7890", // this should be filtered out (not in fields list)
          profile: {
            age: 30,
            location: "NYC",
          },
        },
        {
          name: "Jane Smith",
          email: "jane@example.com",
          age: 25, // this should be filtered out (not in fields list)
          phone: "987-654-3210", // this should be filtered out (not in fields list)
          profile: {
            age: 25,
            location: "LA",
          },
        },
      ];

      const orderData = [
        {
          title: "Order #123",
          description: "Customer order",
          price: 99.99, // this should be filtered out (not in fields list)
          category: "electronics", // this should be filtered out (not in fields list)
          nested_field: {
            items: ["item1", "item2"],
            status: "pending",
          },
        },
        {
          title: "Order #456",
          description: "Another order",
          price: 149.99, // this should be filtered out (not in fields list)
          category: "clothing", // this should be filtered out (not in fields list)
          nested_field: {
            items: ["item3", "item4"],
            status: "shipped",
          },
        },
      ];

      const customers = await Promise.all(
        customerData.map(async (data) => ({
          data,
          ref: await env.firestore.collection("customers").add(data),
        })),
      );
      const orders = await Promise.all(
        orderData.map(async (data) => ({
          data,
          ref: await env.firestore.collection("orders").add(data),
        })),
      );

      await waitForFunctions(2000);

      await env.recreateTypesenseCollections(typesenseCollectionNames());

      await env.triggerBackfill({trigger: true});
      await waitForFunctions(2000);

      const customersDocs = await env.exportDocuments("customers");
      expect(customersDocs.length).toBe(2);

      for (const {data, ref} of customers) {
        const customerDoc = customersDocs.find((doc) => doc["id"] === ref.id);
        expect(customerDoc).toBeDefined();
        expect(customerDoc).toStrictEqual({
          id: ref.id,
          name: data.name,
          email: data.email,
          profile: data.profile,
        });
        expect(customerDoc).not.toHaveProperty("age");
        expect(customerDoc).not.toHaveProperty("phone");
      }

      const ordersDocs = await env.exportDocuments("orders");
      expect(ordersDocs.length).toBe(2);

      for (const {data, ref} of orders) {
        const orderDoc = ordersDocs.find((doc) => doc["id"] === ref.id);
        expect(orderDoc).toBeDefined();
        expect(orderDoc).toStrictEqual({
          id: ref.id,
          title: data.title,
          description: data.description,
          "nested_field.items": data.nested_field.items,
          "nested_field.status": data.nested_field.status,
        });
        expect(orderDoc).not.toHaveProperty("price");
        expect(orderDoc).not.toHaveProperty("category");
      }
    });
  });
});

import {getFirestore} from "firebase-admin/firestore";
import {afterAll, beforeAll, beforeEach, describe, expect, it} from "vitest";
import {TestEnvironment, waitForFunctions} from "./support/testEnvironment.js";

describe("backfillNamedDatabase", () => {
  const env = new TestEnvironment({
    dotenvPath: "test/integration/fixtures/named-database.env",
    outputAllEmulatorLogs: true,
  });

  beforeAll(async () => {
    await env.setup();
  });

  afterAll(async () => {
    await env.teardown();
  });

  beforeEach(async () => {
    await env.clearAllData();
  });

  it("backfills documents from the configured database", async () => {
    const book = {title: "Named Database Book"};
    const bookRef = await env.firestore.collection("books").add(book);
    await waitForFunctions(2000);
    await env.recreateTypesenseCollections(["named_database_books"]);

    await env.triggerBackfill();
    await waitForFunctions(2000);

    expect(await env.exportDocuments("named_database_books")).toStrictEqual([{id: bookRef.id, title: book.title}]);
  });

  it("does not backfill documents from the default database", async () => {
    const defaultDatabase = getFirestore(env.app);
    await defaultDatabase.collection("books").add({title: "Default Database Book"});

    try {
      await env.triggerBackfill();
      await waitForFunctions(2000);

      expect(await env.exportDocuments("named_database_books")).toStrictEqual([]);
    } finally {
      await defaultDatabase.recursiveDelete(defaultDatabase.collection("books"));
    }
  });
});

import {spawn, type ChildProcessWithoutNullStreams} from "node:child_process";
import {readFileSync, rmSync, writeFileSync} from "node:fs";
import path from "node:path";
import {setTimeout as sleep} from "node:timers/promises";
import {fileURLToPath} from "node:url";
import {deleteApp, initializeApp, type App} from "firebase-admin/app";
import {getFirestore, type DocumentData, type Firestore} from "firebase-admin/firestore";
import type {Client} from "typesense";
import {BACKFILL_TRIGGER_DOCUMENT, createCollectionConfigMap, getTypesenseConnectionConfig, type CollectionConfig, type CollectionConfigMap} from "../../../src/config.js";
import {createTypesenseClient} from "../../../src/typesenseClient.js";

export type TypesenseRecord = Readonly<Record<string, unknown>>;

const PROJECT_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../../..");
const FUNCTIONS_ENV_PATH = path.join(PROJECT_ROOT, ".env");
const FUNCTIONS_SECRETS_PATH = path.join(PROJECT_ROOT, ".secret.local");
const FUNCTIONS_EMULATOR_ENV_PATH = path.join(PROJECT_ROOT, ".env.local");
const SECRET_KEYS = new Set(["TYPESENSE_API_KEY"]);
const CONFIG_KEYS = [
  "LOCATION",
  "FIRESTORE_DATABASE_REGION",
  "DATABASE",
  "FIRESTORE_COLLECTION_PATHS",
  "TYPESENSE_COLLECTION_NAMES",
  "FIRESTORE_COLLECTION_FIELDS_LIST",
  "FLATTEN_NESTED_DOCUMENTS_LIST",
  "TYPESENSE_HOSTS",
  "TYPESENSE_PORT",
  "TYPESENSE_PROTOCOL",
  "TYPESENSE_API_KEY",
  "LOG_TYPESENSE_INSERTS",
];

const ANSI_ESCAPE = new RegExp(`${String.fromCharCode(27)}\\[[0-9;]*m`, "g");

function isRecord(value: unknown): value is TypesenseRecord {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function parseEnvFile(contents: string): Map<string, string> {
  const entries = new Map<string, string>();
  for (const rawLine of contents.split("\n")) {
    const line = rawLine.trim();
    if (line === "" || line.startsWith("#")) continue;
    const separator = line.indexOf("=");
    if (separator === -1) continue;
    entries.set(line.slice(0, separator).trim(), line.slice(separator + 1).trim());
  }
  return entries;
}

function serializeEnv(entries: Iterable<readonly [string, string]>): string {
  return [...entries].map(([key, value]) => `${key}=${value}`).join("\n") + "\n";
}

function readProjectId(): string {
  const firebaseRc: unknown = JSON.parse(readFileSync(path.join(PROJECT_ROOT, ".firebaserc"), "utf8"));
  const projects = isRecord(firebaseRc) ? firebaseRc["projects"] : undefined;
  const projectId = isRecord(projects) ? projects["default"] : undefined;
  if (typeof projectId !== "string" || projectId === "") {
    throw new Error("No default project found in .firebaserc");
  }
  return projectId;
}

function logMessageOf(line: string): string {
  const flat = line.replace(ANSI_ESCAPE, "").replace(/^>\s*/, "");
  try {
    const parsed: unknown = JSON.parse(flat);
    return isRecord(parsed) && typeof parsed["message"] === "string" ? parsed["message"] : line;
  } catch {
    return line;
  }
}

export interface TestEnvironmentOptions {
  readonly dotenvPath?: string;
  readonly dotenvConfig?: string;
  readonly outputAllEmulatorLogs?: boolean;
}

export class TestEnvironment {
  readonly #env: Map<string, string>;
  readonly #outputAllEmulatorLogs: boolean;
  #emulator: ChildProcessWithoutNullStreams | undefined;
  #app: App | undefined;
  #firestore: Firestore | undefined;
  #typesense: Client | undefined;
  #shouldCaptureLogs = false;

  capturedEmulatorLogs = "";

  constructor({dotenvPath, dotenvConfig, outputAllEmulatorLogs = false}: TestEnvironmentOptions) {
    if (dotenvPath !== undefined && dotenvConfig !== undefined) {
      throw new Error("Provide either 'dotenvPath' or 'dotenvConfig', not both.");
    }
    const contents = dotenvPath !== undefined ? readFileSync(path.join(PROJECT_ROOT, dotenvPath), "utf8") : (dotenvConfig ?? "");
    this.#env = parseEnvFile(contents);
    this.#outputAllEmulatorLogs = outputAllEmulatorLogs;
  }

  get app(): App {
    if (this.#app === undefined) throw new Error("Test environment is not set up");
    return this.#app;
  }

  get firestore(): Firestore {
    if (this.#firestore === undefined) throw new Error("Test environment is not set up");
    return this.#firestore;
  }

  get typesense(): Client {
    if (this.#typesense === undefined) throw new Error("Test environment is not set up");
    return this.#typesense;
  }

  get collections(): CollectionConfigMap {
    return createCollectionConfigMap();
  }

  get firstCollection(): CollectionConfig {
    const [first] = Object.values(this.collections);
    if (first === undefined) throw new Error("No collections configured");
    return first;
  }

  async setup(): Promise<void> {
    const secrets = [...this.#env].filter(([key]) => SECRET_KEYS.has(key));
    const params = [...this.#env].filter(([key]) => !SECRET_KEYS.has(key));
    rmSync(FUNCTIONS_EMULATOR_ENV_PATH, {force: true});
    writeFileSync(FUNCTIONS_ENV_PATH, serializeEnv(params));
    writeFileSync(FUNCTIONS_SECRETS_PATH, serializeEnv(secrets));

    for (const key of CONFIG_KEYS) Reflect.deleteProperty(process.env, key);
    for (const [key, value] of this.#env) process.env[key] = value;

    const projectId = readProjectId();
    process.env["GCLOUD_PROJECT"] = projectId;
    process.env["FIRESTORE_EMULATOR_HOST"] = "127.0.0.1:8080";

    console.log("Starting Firebase emulator...");
    await this.#startEmulator();

    this.#app = initializeApp({projectId}, `test-${Date.now()}`);
    this.#firestore = getFirestore(this.#app, this.#env.get("DATABASE") ?? "(default)");
    this.#typesense = createTypesenseClient(getTypesenseConnectionConfig());
    this.#shouldCaptureLogs = true;
    console.log("Test environment ready");
  }

  async #startEmulator(): Promise<void> {
    const emulator = spawn("firebase", ["emulators:start", "--only", "functions,firestore"], {
      cwd: PROJECT_ROOT,
      env: {...process.env, FORCE_COLOR: "1"},
    });
    this.#emulator = emulator;

    await new Promise<void>((resolve, reject) => {
      emulator.stdout.on("data", (chunk: Buffer) => {
        const output = chunk.toString().trim();
        const message = logMessageOf(output);
        if (this.#shouldCaptureLogs) this.capturedEmulatorLogs += `${message}\n`;
        if (this.#outputAllEmulatorLogs) console.log(message);
        if (output.includes("All emulators ready")) resolve();
      });
      emulator.stderr.on("data", (chunk: Buffer) => {
        console.error(chunk.toString());
      });
      emulator.on("close", (code) => {
        if (code !== 0) reject(new Error(`Emulator exited unexpectedly with code ${code ?? "null"}`));
      });
    });
  }

  resetCapturedEmulatorLogs(): void {
    this.capturedEmulatorLogs = "";
  }

  async teardown(): Promise<void> {
    this.#shouldCaptureLogs = false;
    const emulator = this.#emulator;
    if (emulator !== undefined && emulator.exitCode === null) {
      const exited = new Promise<void>((resolve) => {
        emulator.on("exit", () => {
          resolve();
        });
      });
      emulator.kill("SIGINT");
      await exited;
    }
    if (this.#app !== undefined) await deleteApp(this.#app);
    rmSync(FUNCTIONS_SECRETS_PATH, {force: true});
    rmSync(FUNCTIONS_EMULATOR_ENV_PATH, {force: true});
  }

  async recreateTypesenseCollections(names: readonly string[], {enableNestedFields = true} = {}): Promise<void> {
    for (const name of names) {
      try {
        await this.typesense.collections(name).delete();
      } catch {
        console.info(`${name} collection not found, proceeding...`);
      }
      await this.typesense.collections().create({
        name,
        fields: [{name: ".*", type: "auto"}],
        enable_nested_fields: enableNestedFields,
      });
    }
  }

  async clearAllData(): Promise<void> {
    for (const config of Object.values(this.collections)) {
      await this.firestore.recursiveDelete(this.firestore.collection(config.firestorePath.split("/")[0] ?? config.firestorePath));
    }
    await this.recreateTypesenseCollections(Object.values(this.collections).map((config) => config.typesenseCollection));
  }

  async exportDocuments(collectionName: string): Promise<TypesenseRecord[]> {
    const exported = await this.typesense.collections(collectionName).documents().export();
    return exported
      .split("\n")
      .filter((line) => line.trim() !== "")
      .map((line) => {
        const parsed: unknown = JSON.parse(line);
        if (!isRecord(parsed)) throw new Error(`Unexpected export line: ${line}`);
        return parsed;
      });
  }

  async triggerBackfill(data: DocumentData = {trigger: true}): Promise<void> {
    await this.firestore.doc(BACKFILL_TRIGGER_DOCUMENT).set(data);
  }
}

export async function waitForFunctions(ms: number): Promise<void> {
  await sleep(ms);
}

import {createServer, type IncomingMessage, type Server} from "node:http";
import type {AddressInfo} from "node:net";

export interface RecordedRequest {
  readonly method: string;
  readonly url: string;
  readonly body: string;
}

function defaultResponseBody(request: RecordedRequest, status: number): string {
  if (status === 404) return JSON.stringify({message: "Could not find a document with id: doc1"});
  if (request.url.includes("/documents/import")) {
    return request.body
      .split("\n")
      .filter((line) => line !== "")
      .map(() => JSON.stringify({success: true}))
      .join("\n");
  }
  return "{}";
}

export class StubTypesense {
  readonly requests: RecordedRequest[] = [];
  status = 200;
  readonly #server: Server = createServer((request: IncomingMessage, response) => {
    let body = "";
    request.on("data", (chunk: Buffer) => {
      body += chunk.toString();
    });
    request.on("end", () => {
      const recorded = {method: request.method ?? "", url: request.url ?? "", body};
      this.requests.push(recorded);
      const contentType = recorded.url.includes("/documents/import") ? "text/plain" : "application/json";
      response.writeHead(this.status, {"Content-Type": contentType});
      response.end(defaultResponseBody(recorded, this.status));
    });
  });

  async start(): Promise<number> {
    await new Promise<void>((resolve) => {
      this.#server.listen(0, "127.0.0.1", resolve);
    });
    const address = this.#server.address();
    if (address === null || typeof address === "string") throw new Error("Stub server has no port");
    const {port}: AddressInfo = address;
    return port;
  }

  async stop(): Promise<void> {
    await new Promise<void>((resolve, reject) => {
      this.#server.close((err) => {
        if (err) reject(err);
        else resolve();
      });
    });
  }
}

