import {afterAll, beforeAll, beforeEach, describe, expect, it} from "vitest";
import {handleBackfillTrigger, type FirestoreLike} from "../../src/backfill.js";
import {StubTypesense} from "./support/stubTypesense.js";

type FakeQuery = ReturnType<FirestoreLike["collectionGroup"]>;
type FakeDocument = Parameters<FakeQuery["startAfter"]>[0];

function fakeDocument(path: string): FakeDocument {
  const id = path.split("/").at(-1) ?? path;
  return {id, ref: {path}, data: () => ({title: id})};
}

function fakeQuery(docs: readonly FakeDocument[], start = 0, limit = docs.length): FakeQuery {
  return {
    startAfter: (document) => fakeQuery(docs, docs.indexOf(document) + 1, limit),
    limit: (pageSize) => fakeQuery(docs, start, pageSize),
    get: () => {
      const page = docs.slice(start, start + limit);
      return Promise.resolve({empty: page.length === 0, size: page.length, docs: page});
    },
  };
}

function fakeFirestore(collectionGroup: readonly FakeDocument[]): FirestoreLike {
  return {
    collection: () => fakeQuery([]),
    collectionGroup: () => fakeQuery(collectionGroup),
  };
}

function books(count: number, parent: string): FakeDocument[] {
  return Array.from({length: count}, (_, index) => fakeDocument(`${parent}/books/${parent.replaceAll("/", "-")}-${index}`));
}

const trigger = {get: (field: unknown): unknown => (field === "trigger" ? true : undefined)};

describe("handleBackfillTrigger", () => {
  const typesense = new StubTypesense();

  const importedBatchSizes = (): number[] =>
    typesense.requests.filter(({url}) => url.startsWith("/collections/user_books/documents/import")).map(({body}) => body.split("\n").filter((line) => line !== "").length);

  beforeAll(async () => {
    const port = await typesense.start();
    process.env["FIRESTORE_COLLECTION_PATHS"] = "users/{userId}/books";
    process.env["TYPESENSE_COLLECTION_NAMES"] = "user_books";
    process.env["TYPESENSE_HOSTS"] = "127.0.0.1";
    process.env["TYPESENSE_PORT"] = String(port);
    process.env["TYPESENSE_PROTOCOL"] = "http";
    process.env["TYPESENSE_API_KEY"] = "xyz";
  });

  afterAll(async () => {
    await typesense.stop();
  });

  beforeEach(() => {
    typesense.requests.length = 0;
  });

  it("keeps paging when documents outside the configured path shorten a full page", async () => {
    const [first, ...rest] = books(999, "users/u1");
    if (first === undefined) throw new Error("No documents");
    const documents = [first, fakeDocument("shelves/s1/books/unrelated"), ...rest, ...books(1, "users/u2")];

    await handleBackfillTrigger(trigger, fakeFirestore(documents));

    expect(importedBatchSizes()).toStrictEqual([999, 1]);
  });

  it("keeps paging past a full page of documents outside the configured path", async () => {
    await handleBackfillTrigger(trigger, fakeFirestore([...books(1000, "shelves/s1"), ...books(2, "users/u1")]));

    expect(importedBatchSizes()).toStrictEqual([2]);
  });

  it("skips documents of a same-named subcollection nested below the configured path", async () => {
    await handleBackfillTrigger(trigger, fakeFirestore([...books(2, "users/u1"), ...books(1, "users/u1/books/b1")]));

    expect(importedBatchSizes()).toStrictEqual([2]);
  });
});

import {describe, expect, it} from "vitest";
import {GeoPoint, getFirestore, Timestamp} from "firebase-admin/firestore";
import {initializeApp} from "firebase-admin/app";
import {createTypesenseDocument} from "../../src/document.js";

describe("Utils", () => {
  describe("createTypesenseDocument", () => {
    describe("Basic functionality", () => {
      it("creates a Typesense document with all fields when no fields specified", () => {
        const documentSnapshot = {
          data: () => ({
            title: "Book Title",
            author: "Author Name",
            rating: 4.5,
            price: 29.99,
          }),
          id: "doc123",
        };

        const collectionConfig = {
          fields: [],
          flattenNested: false,
          typesenseCollection: "books",
        };

        const result = createTypesenseDocument(documentSnapshot, collectionConfig, {});
        expect(result).toEqual({
          id: "doc123",
          title: "Book Title",
          author: "Author Name",
          rating: 4.5,
          price: 29.99,
        });
      });

      it("creates a Typesense document with only specified fields", () => {
        const documentSnapshot = {
          data: () => ({
            title: "Book Title",
            author: "Author Name",
            rating: 4.5,
            price: 29.99,
            isbn: "1234567890",
          }),
          id: "doc123",
        };

        const collectionConfig = {
          fields: ["title", "author", "rating"],
          flattenNested: false,
          typesenseCollection: "books",
        };

        const result = createTypesenseDocument(documentSnapshot, collectionConfig, {});
        expect(result).toEqual({
          id: "doc123",
          title: "Book Title",
          author: "Author Name",
          rating: 4.5,
        });
      });

      it("adds context parameters to the document", () => {
        const documentSnapshot = {
          data: () => ({
            title: "Book Title",
            author: "Author Name",
          }),
          id: "doc123",
        };

        const collectionConfig = {
          fields: ["title", "author"],
          flattenNested: false,
          typesenseCollection: "books",
        };

        const contextParams = {
          userId: "user123",
          category: "fiction",
        };

        const result = createTypesenseDocument(documentSnapshot, collectionConfig, contextParams);
        expect(result).toEqual({
          id: "doc123",
          title: "Book Title",
          author: "Author Name",
          userId: "user123",
          category: "fiction",
        });
      });

      it("excludes docId from context parameters", () => {
        const documentSnapshot = {
          data: () => ({
            title: "Book Title",
            author: "Author Name",
          }),
          id: "doc123",
        };

        const collectionConfig = {
          fields: ["title", "author"],
          flattenNested: false,
          typesenseCollection: "books",
        };

        const contextParams = {
          docId: "should-be-excluded",
          userId: "user123",
        };

        const result = createTypesenseDocument(documentSnapshot, collectionConfig, contextParams);
        expect(result).toEqual({
          id: "doc123",
          title: "Book Title",
          author: "Author Name",
          userId: "user123",
        });
        expect(result).not.toHaveProperty("docId");
      });

      it("throws error when document data is null", () => {
        const documentSnapshot = {
          data: () => null,
          id: "doc123",
        };

        const collectionConfig = {
          fields: ["title", "author"],
          flattenNested: false,
          typesenseCollection: "books",
        };

        expect(() => createTypesenseDocument(documentSnapshot, collectionConfig, {})).toThrow("Document data is null");
      });
    });

    describe("Nested fields handling without flattening", () => {
      it("extracts nested fields using dot notation", () => {
        const documentSnapshot = {
          data: () => ({
            user: {
              name: "John Doe",
              address: {
                city: "New York",
                country: "USA",
              },
            },
            tags: ["tag1", "tag2"],
          }),
          id: "doc123",
        };

        const collectionConfig = {
          fields: ["user.name", "user.address.city", "tags"],
          flattenNested: false,
          typesenseCollection: "books",
        };

        const result = createTypesenseDocument(documentSnapshot, collectionConfig, {});
        expect(result).toEqual({
          id: "doc123",
          user: {name: "John Doe", address: {city: "New York"}},
          tags: ["tag1", "tag2"],
        });
      });

      it("handles missing nested fields gracefully", () => {
        const documentSnapshot = {
          data: () => ({
            user: {
              name: "John Doe",
            },
          }),
          id: "doc123",
        };

        const collectionConfig = {
          fields: ["user.name", "user.address.city"],
          flattenNested: false,
          typesenseCollection: "books",
        };

        const result = createTypesenseDocument(documentSnapshot, collectionConfig, {});
        expect(result).toEqual({
          id: "doc123",
          user: {
            name: "John Doe",
          },
        });
      });

      it("handles array indexing in dot notation", () => {
        const documentSnapshot = {
          data: () => ({
            comments: [
              {author: "Alice", text: "Great post!"},
              {author: "Bob", text: "Thanks for sharing.", likes: 5},
            ],
          }),
          id: "doc123",
        };

        const collectionConfig = {
          fields: ["comments.author", "comments.text", "comments.likes"],
          flattenNested: false,
          typesenseCollection: "books",
        };

        const result = createTypesenseDocument(documentSnapshot, collectionConfig, {});
        expect(result).toEqual({
          id: "doc123",
          comments: [
            {author: "Alice", text: "Great post!"},
            {author: "Bob", text: "Thanks for sharing.", likes: 5},
          ],
        });
      });
