      expect(createTypesenseDocument(documentSnapshot, {fields: ["comments.author", "comments.likes"], flattenNested: true}, {})).toStrictEqual({
        "comments.author": ["Alice", "Bob"],
        "comments.likes": [5],
        id: "doc123",
