    it("does not throw on a dotted field that crosses a null value", () => {
      const documentSnapshot = {id: "doc123", data: () => ({title: "T", nullField: null})};

      expect(createTypesenseDocument(documentSnapshot, {fields: ["title", "nullField.inner"], flattenNested: false}, {})).toStrictEqual({
        title: "T",
        id: "doc123",
      });
    });
  });
});

import {describe, expect, it} from "vitest";
import * as utils from "../../src/paths.js";

describe("paths", () => {
  describe("Parsing static firestore path", () => {
    it("Static firestore path should do nothing", () => {
      const staticPathVars1 = utils.parseFirestorePath("books");
      expect(staticPathVars1).toEqual({});

      const staticPathVars2 = utils.parseFirestorePath("books/123");
      expect(staticPathVars2).toEqual({});

      const staticPathVars5 = utils.parseFirestorePath("books/123/chapter/456/title");
      expect(staticPathVars5).toEqual({});
    });

    it("Returns null when the selector is longer than the path", () => {
      const fullPath = "/users/123/books/456/author";
      const selector = "/users/123/books/456/author/{authorId}/email";

      const vars = utils.pathMatchesSelector(fullPath, selector);
      expect(vars).toBeNull();
    });
  });

  describe("Parsing dynamic firestore path", () => {
    it("Dynamic firestore path should return placeholders", () => {
      const dynamicPath2 = "books/{bookId}/chapter";
      const dynamicPathVars2 = utils.parseFirestorePath(dynamicPath2);
      expect(dynamicPathVars2).toEqual({bookId: 1});

      const actualPathVars2 = utils.pathMatchesSelector("books/123/chapter", dynamicPath2);
      expect(actualPathVars2).toEqual({bookId: "123"});

      const dynamicPath5 = "books/{bookId}/chapter/{chapterId}/title";
      const dynamicPathVars5 = utils.parseFirestorePath(dynamicPath5);
      expect(dynamicPathVars5).toEqual({bookId: 1, chapterId: 3});

      const actualPathVars5 = utils.pathMatchesSelector("books/123/chapter/456/title", dynamicPath5);
      expect(actualPathVars5).toEqual({bookId: "123", chapterId: "456"});
    });
  });

  describe("pathMatchesSelector", () => {
    it("should return extracted placeholders for a matching path and selector", () => {
      const path = "users/123/library/456/books/789";
      const selector = "users/{userId}/library/{libraryId}/books";
      const result = utils.pathMatchesSelector(path, selector);
      expect(result).toEqual({userId: "123", libraryId: "456"});
    });

    it("should return null for a non-matching path and selector", () => {
      const path = "users/123/library/456/magazines/789";
      const selector = "users/{userId}/library/{libraryId}/books/{bookId}";
      const result = utils.pathMatchesSelector(path, selector);
      expect(result).toBeNull();
    });

    it("should return null if the path is shorter than the selector", () => {
      const path = "users/123/library/456";
      const selector = "users/{userId}/library/{libraryId}/books/{bookId}";
      const result = utils.pathMatchesSelector(path, selector);
      expect(result).toBeNull();
    });

    it("should handle selectors without placeholders", () => {
      const path = "users/123/library";
      const selector = "users/123/library";
      const result = utils.pathMatchesSelector(path, selector);
      expect(result).toEqual({});
    });

    it("should return null if the static segments of path and selector do not match", () => {
      const path = "users/123/libraries/456";
      const selector = "users/{userId}/library/{libraryId}";
      const result = utils.pathMatchesSelector(path, selector);
      expect(result).toBeNull();
    });

    it("should throw an error for an invalid path", () => {
      const path = null;
      const selector = "users/{userId}/library/{libraryId}";
      expect(() => {
        utils.pathMatchesSelector(path, selector);
      }).toThrow("Invalid path: Path must be a non-empty string.");
    });

    it("should throw an error for an invalid selector", () => {
      const path = "users/123/library/456";
      const selector = null;
      expect(() => {
        utils.pathMatchesSelector(path, selector);
      }).toThrow("Invalid selector: Selector must be a non-empty string.");
    });

    it("should extract placeholders even when additional path segments exist", () => {
      const path = "users/123/library/456/books/789/reviews/101";
      const selector = "users/{userId}/library/{libraryId}/books";
      const result = utils.pathMatchesSelector(path, selector);
      expect(result).toEqual({userId: "123", libraryId: "456"});
    });

    it("should handle paths and selectors with trailing slashes", () => {
      const path = "users/123/library/456/";
      const selector = "users/{userId}/library";
      const result = utils.pathMatchesSelector(path, selector);
      expect(result).toEqual({userId: "123"});
    });
  });

  describe("matchDocumentPath", () => {
    it("returns the placeholders for a document directly in the collection", () => {
      expect(utils.matchDocumentPath("users/123/books/456", "users/{userId}/books")).toEqual({userId: "123"});
      expect(utils.matchDocumentPath("/users/123/", "users")).toEqual({});
    });

    it("returns null for a document in a subcollection of the collection", () => {
      expect(utils.matchDocumentPath("users/123/books/456", "users")).toBeNull();
      expect(utils.matchDocumentPath("users/123/books/456/books/789", "users/{userId}/books")).toBeNull();
    });

    it("returns null for a path that is not a document of the collection", () => {
      expect(utils.matchDocumentPath("users", "users")).toBeNull();
      expect(utils.matchDocumentPath("shelves/1/books/2", "users/{userId}/books")).toBeNull();
    });
  });

  describe("parseFirestorePath validation", () => {
    it("throws on an empty path", () => {
      expect(() => utils.parseFirestorePath("")).toThrow("Invalid Firestore path: Path must be a non-empty string.");
    });

    it("throws on duplicate placeholders, including one in the first segment", () => {
      expect(() => utils.parseFirestorePath("{a}/x/{a}")).toThrow("Duplicate placeholder detected: a");
    });
  });
});

import {beforeEach, describe, expect, it} from "vitest";
import {assertNoRemovedParams, createCollectionConfigMap, getTypesenseConnectionConfig, parseBooleanList, parseCommaSeparated, parsePipeSeparated} from "../../src/config.js";

const COLLECTION_KEYS = [
  "FIRESTORE_COLLECTION_PATHS",
  "TYPESENSE_COLLECTION_NAMES",
  "FIRESTORE_COLLECTION_FIELDS_LIST",
  "FLATTEN_NESTED_DOCUMENTS_LIST",
  "FIRESTORE_COLLECTION_PATH",
  "TYPESENSE_COLLECTION_NAME",
  "FIRESTORE_COLLECTION_FIELDS",
  "FLATTEN_NESTED_DOCUMENTS",
  "TYPESENSE_HOSTS",
  "TYPESENSE_PORT",
  "TYPESENSE_PROTOCOL",
  "TYPESENSE_API_KEY",
];

describe("Multi-Collection Configuration", () => {
  beforeEach(() => {
    for (const key of COLLECTION_KEYS) Reflect.deleteProperty(process.env, key);
  });

  describe("parseCommaSeparated", () => {
    it("should parse comma-separated strings correctly", () => {
      expect(parseCommaSeparated("a,b,c")).toEqual(["a", "b", "c"]);
      expect(parseCommaSeparated("a, b , c")).toEqual(["a", "b", "c"]);
      expect(parseCommaSeparated("")).toEqual([]);
      expect(parseCommaSeparated(null)).toEqual([]);
      expect(parseCommaSeparated(undefined)).toEqual([]);
    });
  });

  describe("parsePipeSeparated", () => {
    it("should parse pipe-separated strings correctly", () => {
      expect(parsePipeSeparated("a,b|c,d")).toEqual([
        ["a", "b"],
        ["c", "d"],
      ]);
      expect(parsePipeSeparated("a|b|c")).toEqual([["a"], ["b"], ["c"]]);
      expect(parsePipeSeparated("")).toEqual([]);
      expect(parsePipeSeparated(null)).toEqual([]);
    });
  });

  describe("parseBooleanList", () => {
    it("should parse boolean lists correctly", () => {
      expect(parseBooleanList("true,false,true")).toEqual([true, false, true]);
      expect(parseBooleanList("false,true")).toEqual([false, true]);
      expect(parseBooleanList("")).toEqual([]);
      expect(parseBooleanList(null)).toEqual([]);
    });
  });

  describe("createCollectionConfigMap", () => {
    it("should create collection map from new multi-collection parameters", () => {
      process.env["FIRESTORE_COLLECTION_PATHS"] = "users,products";
      process.env["TYPESENSE_COLLECTION_NAMES"] = "users,products";
      process.env["FIRESTORE_COLLECTION_FIELDS_LIST"] = "name,email|title,description";
      process.env["FLATTEN_NESTED_DOCUMENTS_LIST"] = "false,true";

      expect(createCollectionConfigMap()).toEqual({
        users: {firestorePath: "users", typesenseCollection: "users", fields: ["name", "email"], flattenNested: false},
        products: {firestorePath: "products", typesenseCollection: "products", fields: ["title", "description"], flattenNested: true},
      });
    });

    it("should handle empty fields and flatten settings", () => {
      process.env["FIRESTORE_COLLECTION_PATHS"] = "users,products";
      process.env["TYPESENSE_COLLECTION_NAMES"] = "users,products";

      expect(createCollectionConfigMap()).toEqual({
        users: {firestorePath: "users", typesenseCollection: "users", fields: [], flattenNested: false},
        products: {firestorePath: "products", typesenseCollection: "products", fields: [], flattenNested: false},
      });
    });

    it("should skip empty field lists between pipes", () => {
      process.env["FIRESTORE_COLLECTION_PATHS"] = "users,products,customers";
      process.env["TYPESENSE_COLLECTION_NAMES"] = "users,products,customers";
      process.env["FIRESTORE_COLLECTION_FIELDS_LIST"] = "||name,email";

      expect(Object.values(createCollectionConfigMap()).map((config) => config.fields)).toEqual([[], [], ["name", "email"]]);
    });

    it("should throw error for mismatched collection counts", () => {
      process.env["FIRESTORE_COLLECTION_PATHS"] = "users,products";
      process.env["TYPESENSE_COLLECTION_NAMES"] = "users";

      expect(() => createCollectionConfigMap()).toThrow("Mismatch in collection counts: 2 Firestore paths vs 1 Typesense names");
    });

    it("should throw error when no collection config is provided", () => {
      expect(() => createCollectionConfigMap()).toThrow("No Firestore collection config found. Set FIRESTORE_COLLECTION_PATHS and TYPESENSE_COLLECTION_NAMES.");
    });

    it("should throw error when only one of the collection params is set", () => {
      process.env["FIRESTORE_COLLECTION_PATHS"] = "users,products";

      expect(() => createCollectionConfigMap()).toThrow("Mismatch in collection counts: 2 Firestore paths vs 0 Typesense names");
    });
  });

  describe("assertNoRemovedParams", () => {
    it("should explain how to replace the removed single-collection params", () => {
      process.env["FIRESTORE_COLLECTION_PATH"] = "books";
      process.env["TYPESENSE_COLLECTION_NAME"] = "books_firestore";
      process.env["FIRESTORE_COLLECTION_FIELDS"] = "title,author";
      process.env["FLATTEN_NESTED_DOCUMENTS"] = "";

      expect(() => {
        assertNoRemovedParams();
      }).toThrow(
        "were removed in 4.0.0. Replace them in your configuration with:\n" +
          "FIRESTORE_COLLECTION_PATHS=books\nTYPESENSE_COLLECTION_NAMES=books_firestore\nFIRESTORE_COLLECTION_FIELDS_LIST=title,author\n" +
          "See https://github.com/typesense/firestore-typesense-search/blob/master/UPGRADING.md",
      );
    });

    it("should pass when the collection params are set, even if removed params remain", () => {
      process.env["FIRESTORE_COLLECTION_PATH"] = "books";
      process.env["TYPESENSE_COLLECTION_NAME"] = "books";
      process.env["FIRESTORE_COLLECTION_PATHS"] = "users";
      process.env["TYPESENSE_COLLECTION_NAMES"] = "users";

      expect(() => {
        assertNoRemovedParams();
      }).not.toThrow();
      expect(Object.keys(createCollectionConfigMap())).toEqual(["users"]);
    });

    it("should pass when nothing is configured yet, so a first deploy can prompt for the params", () => {
      expect(() => {
        assertNoRemovedParams();
      }).not.toThrow();
    });
  });

  describe("collections", () => {
    it("should key collections by Firestore path in configured order", () => {
      process.env["FIRESTORE_COLLECTION_PATHS"] = "users,products";
      process.env["TYPESENSE_COLLECTION_NAMES"] = "users,products";

      expect(Object.keys(createCollectionConfigMap())).toEqual(["users", "products"]);
    });
  });

  describe("getTypesenseConnectionConfig", () => {
    it("should default to https on port 443", () => {
      process.env["TYPESENSE_HOSTS"] = "a.typesense.net, b.typesense.net";
      process.env["TYPESENSE_API_KEY"] = "secret";

      expect(getTypesenseConnectionConfig()).toEqual({
        nodes: [
          {host: "a.typesense.net", port: 443, protocol: "https"},
          {host: "b.typesense.net", port: 443, protocol: "https"},
        ],
        apiKey: "secret",
      });
    });

    it("should read TYPESENSE_PORT and TYPESENSE_PROTOCOL from the environment", () => {
      process.env["TYPESENSE_HOSTS"] = "localhost";
      process.env["TYPESENSE_PORT"] = "8108";
      process.env["TYPESENSE_PROTOCOL"] = "http";
      process.env["TYPESENSE_API_KEY"] = "xyz";

      expect(getTypesenseConnectionConfig()).toEqual({nodes: [{host: "localhost", port: 8108, protocol: "http"}], apiKey: "xyz"});
    });

    it("should reject an invalid port or protocol", () => {
      process.env["TYPESENSE_HOSTS"] = "localhost";
      process.env["TYPESENSE_PORT"] = "abc";
      expect(() => getTypesenseConnectionConfig()).toThrow('Invalid TYPESENSE_PORT "abc"');

      process.env["TYPESENSE_PORT"] = "8108";
      process.env["TYPESENSE_PROTOCOL"] = "ftp";
      expect(() => getTypesenseConnectionConfig()).toThrow('Invalid TYPESENSE_PROTOCOL "ftp"');
    });
  });
});

import {afterAll, beforeAll, beforeEach, describe, expect, it} from "vitest";
import {TestEnvironment, waitForFunctions} from "./support/testEnvironment.js";

describe("indexOnWriteMultiCollectionSubcollections", () => {
  const env = new TestEnvironment({
    dotenvPath: "test/integration/fixtures/multi-collection-subcollections.env",
    outputAllEmulatorLogs: false,
  });

  beforeAll(async () => {
    await env.setup();
  });

  afterAll(async () => {
    await env.teardown();
  });

  beforeEach(async () => {
    await env.recreateTypesenseCollections(["user_books", "store_products"]);
  });

  describe("Subcollection Indexing", () => {
    it("should index documents from user subcollections", async () => {
      const userId = "user123";
      const bookData = {
        title: "The Great Gatsby",
        author: "F. Scott Fitzgerald",
        rating: 4.5,
      };

      await env.firestore.collection("users").doc(userId).set({
        name: "John Doe",
        email: "john@example.com",
      });

      const bookRef = await env.firestore.collection("users").doc(userId).collection("books").add(bookData);

      await waitForFunctions(3000);

      expect(await env.exportDocuments("user_books")).toStrictEqual([
        {
          id: bookRef.id,
          title: bookData.title,
          author: bookData.author,
          rating: bookData.rating,
          userId: userId,
        },
      ]);
    });

    it("should index documents from store subcollections", async () => {
      const storeId = "store456";
      const productData = {
        name: "iPhone 15",
        price: 999.99,
        category: "electronics",
        details: {
          color: "black",
          storage: "256GB",
        },
      };

      await env.firestore.collection("stores").doc(storeId).set({
        name: "Apple Store",
        location: "New York",
      });

      const productRef = await env.firestore.collection("stores").doc(storeId).collection("products").add(productData);

      await waitForFunctions(3000);

      expect(await env.exportDocuments("store_products")).toStrictEqual([
        {
          id: productRef.id,
          name: productData.name,
          price: productData.price,
          category: productData.category,
          storeId: storeId,
        },
      ]);
    });

    it("should handle updates in subcollections", async () => {
      const userId = "user789";
      const bookData = {
        title: "1984",
        author: "George Orwell",
        rating: 3.5,
      };

      await env.firestore.collection("users").doc(userId).set({
        name: "Jane Doe",
        email: "jane@example.com",
      });

      const bookRef = await env.firestore.collection("users").doc(userId).collection("books").add(bookData);

      await waitForFunctions(3000);

      await bookRef.update({
        title: "1984 (Updated)",
        rating: 4.5,
      });

      await waitForFunctions(2000);

      const booksDocs = await env.exportDocuments("user_books");

      console.log("Updated document:", booksDocs[0]);
      expect(booksDocs).toStrictEqual([
        {
          id: bookRef.id,
          title: "1984 (Updated)",
          author: "George Orwell",
          rating: 4.5,
          userId: userId,
        },
      ]);
    });

    it("should handle deletions in subcollections", async () => {
      const userId = "user999";
      const bookData = {
        title: "To Kill a Mockingbird",
        author: "Harper Lee",
        rating: 4.8,
      };

      await env.firestore.collection("users").doc(userId).set({
        name: "Bob Smith",
        email: "bob@example.com",
      });

      const bookRef = await env.firestore.collection("users").doc(userId).collection("books").add(bookData);

      await waitForFunctions(3000);

      await bookRef.delete();

      await waitForFunctions(3000);

      expect(await env.exportDocuments("user_books")).toEqual([]);
    });

    it("should handle multiple subcollections simultaneously", async () => {
      const userId1 = "user1";
      const userId2 = "user2";
      const storeId = "store1";

      const book1Data = {title: "Book 1", author: "Author 1", rating: 3.5};
      const book2Data = {title: "Book 2", author: "Author 2", rating: 4.5};
      const productData = {name: "Product 1", price: 100, category: "tech"};

      await env.firestore.collection("users").doc(userId1).set({name: "User 1"});
      await env.firestore.collection("users").doc(userId2).set({name: "User 2"});
      await env.firestore.collection("stores").doc(storeId).set({name: "Store 1"});

      const book1Ref = await env.firestore.collection("users").doc(userId1).collection("books").add(book1Data);
      const book2Ref = await env.firestore.collection("users").doc(userId2).collection("books").add(book2Data);
      const productRef = await env.firestore.collection("stores").doc(storeId).collection("products").add(productData);

      await waitForFunctions(3000);

      const booksDocs = await env.exportDocuments("user_books");
      const productsDocs = await env.exportDocuments("store_products");

      expect(booksDocs.length).toBe(2);
      expect(productsDocs.length).toBe(1);

      const book1Doc = booksDocs.find((doc) => doc["id"] === book1Ref.id);
      const book2Doc = booksDocs.find((doc) => doc["id"] === book2Ref.id);

      expect(book1Doc).toStrictEqual({
        id: book1Ref.id,
        title: book1Data.title,
        author: book1Data.author,
        rating: book1Data.rating,
        userId: userId1,
      });

      expect(book2Doc).toStrictEqual({
        id: book2Ref.id,
        title: book2Data.title,
        author: book2Data.author,
        rating: book2Data.rating,
        userId: userId2,
      });

      expect(productsDocs).toStrictEqual([
        {
          id: productRef.id,
          name: productData.name,
          price: productData.price,
          category: productData.category,
          storeId: storeId,
        },
      ]);
    });
  });
});

import {afterAll, beforeAll, beforeEach, describe, expect, it} from "vitest";
import {TestEnvironment, waitForFunctions} from "./support/testEnvironment.js";

describe("indexOnWriteMultiCollection", () => {
  const env = new TestEnvironment({
    dotenvPath: "test/integration/fixtures/multi-collection.env",
    outputAllEmulatorLogs: false,
  });

  beforeAll(async () => {
    await env.setup();
    console.log("Available collections:", Object.keys(env.collections));
  });

  afterAll(async () => {
    await env.teardown();
  });

  beforeEach(async () => {
    await env.recreateTypesenseCollections(Object.values(env.collections).map((c) => c.typesenseCollection));
  });

  describe("Basic Data Types", () => {
    it("should index string values on writes to multiple collections", async () => {
      const userData = {name: "John Doe"};
      const productData = {title: "Sample Product"};

      const userRef = await env.firestore.collection("users").add(userData);
      const productRef = await env.firestore.collection("products").add(productData);

      await waitForFunctions(3000);

      expect(await env.exportDocuments("users")).toStrictEqual([{id: userRef.id, name: userData.name}]);
      expect(await env.exportDocuments("products")).toStrictEqual([{id: productRef.id, title: productData.title}]);
    });

    it("should index numeric values on writes to multiple collections", async () => {
      const userData = {age: 30};
      const productData = {price: 99.99};

      const userRef = await env.firestore.collection("users").add(userData);
      const productRef = await env.firestore.collection("products").add(productData);

      await waitForFunctions(3000);

      expect(await env.exportDocuments("users")).toStrictEqual([{id: userRef.id, age: userData.age}]);
      expect(await env.exportDocuments("products")).toStrictEqual([{id: productRef.id, price: productData.price}]);
    });

    it("should index boolean values on writes to multiple collections", async () => {
      const userData = {isActive: true};
      const productData = {isAvailable: false};

      const userRef = await env.firestore.collection("users").add(userData);
      const productRef = await env.firestore.collection("products").add(productData);

      await waitForFunctions(3000);

      expect(await env.exportDocuments("users")).toStrictEqual([{id: userRef.id, isActive: userData.isActive}]);
      expect(await env.exportDocuments("products")).toStrictEqual([{id: productRef.id, isAvailable: productData.isAvailable}]);
    });

    it("should index null values on writes to multiple collections", async () => {
      const userData = {name: null};
      const productData = {description: null};

      const userRef = await env.firestore.collection("users").add(userData);
      const productRef = await env.firestore.collection("products").add(productData);

      await waitForFunctions(3000);

      expect(await env.exportDocuments("users")).toStrictEqual([{id: userRef.id}]);
      expect(await env.exportDocuments("products")).toStrictEqual([{id: productRef.id}]);
    });

    it("should index timestamp values on writes to multiple collections", async () => {
      const now = new Date();
      const userData = {createdAt: now};
      const productData = {updatedAt: now};

      const userRef = await env.firestore.collection("users").add(userData);
      const productRef = await env.firestore.collection("products").add(productData);

      await waitForFunctions(3000);

      expect(await env.exportDocuments("users")).toStrictEqual([{id: userRef.id, createdAt: Math.floor(now.getTime() / 1000)}]);
      expect(await env.exportDocuments("products")).toStrictEqual([{id: productRef.id, updatedAt: Math.floor(now.getTime() / 1000)}]);
    });

    it("should index geo point values on writes to multiple collections", async () => {
      const userData = {location: {latitude: 40.7128, longitude: -74.006}};
      const productData = {shippingLocation: {latitude: 34.0522, longitude: -118.2437}};

      await env.firestore.collection("users").add(userData);
      await env.firestore.collection("products").add(productData);

      await waitForFunctions(3000);

      const usersDocs = await env.exportDocuments("users");
      const productsDocs = await env.exportDocuments("products");

      expect(usersDocs.length).toBe(1);
      expect(productsDocs.length).toBe(1);
      const [userDoc] = usersDocs;
      const [productDoc] = productsDocs;
      expect(userDoc?.["location"]).toEqual([40.7128, -74.006]);
      expect(productDoc?.["shippingLocation"]).toEqual([34.0522, -118.2437]);
    });

    it("should index array values on writes to multiple collections", async () => {
      const userData = {tags: ["admin", "user", "premium"]};
      const productData = {categories: ["electronics", "gadgets"]};

      const userRef = await env.firestore.collection("users").add(userData);
      const productRef = await env.firestore.collection("products").add(productData);

      await waitForFunctions(3000);

      expect(await env.exportDocuments("users")).toStrictEqual([{id: userRef.id, tags: userData.tags}]);
      expect(await env.exportDocuments("products")).toStrictEqual([{id: productRef.id, categories: productData.categories}]);
    });
  });

  describe("Nested Fields", () => {
    it("should index nested fields without flattening for users collection", async () => {
      const userData = {
        profile: {
          age: 30,
          location: "New York",
          preferences: {
            theme: "dark",
            language: "en",
          },
        },
      };

      const userRef = await env.firestore.collection("users").add(userData);

      await waitForFunctions(3000);

      expect(await env.exportDocuments("users")).toStrictEqual([
        {
          id: userRef.id,
          profile: {
            age: 30,
            location: "New York",
            preferences: {
              theme: "dark",
              language: "en",
            },
          },
        },
      ]);
    });

    it("should index nested fields with flattening for products collection", async () => {
      const productData = {
        details: {
          brand: "Apple",
          specs: {
            color: "black",
            weight: "200g",
          },
        },
      };

      const productRef = await env.firestore.collection("products").add(productData);

      await waitForFunctions(3000);

      expect(await env.exportDocuments("products")).toStrictEqual([
        {
          id: productRef.id,
          "details.brand": "Apple",
          "details.specs.color": "black",
          "details.specs.weight": "200g",
        },
      ]);
    });
  });

  describe("Document Operations", () => {
    it("should handle document updates in multiple collections", async () => {
      const userData = {name: "John Doe", email: "john@example.com"};
      const productData = {title: "Sample Product", price: 99.99};

      const userRef = await env.firestore.collection("users").add(userData);
      const productRef = await env.firestore.collection("products").add(productData);

      await waitForFunctions(3000);

      await userRef.update({name: "John Updated", email: "john.updated@example.com"});
      await productRef.update({title: "Updated Product", price: 149.99});

      await waitForFunctions(3000);

      expect(await env.exportDocuments("users")).toStrictEqual([
        {
          id: userRef.id,
          name: "John Updated",
          email: "john.updated@example.com",
        },
      ]);

      expect(await env.exportDocuments("products")).toStrictEqual([
        {
          id: productRef.id,
          title: "Updated Product",
          price: 149.99,
        },
      ]);
    });

    it("should handle document deletions in multiple collections", async () => {
      const userData = {name: "John Doe"};
      const productData = {title: "Sample Product"};

      const userRef = await env.firestore.collection("users").add(userData);
      const productRef = await env.firestore.collection("products").add(productData);

      await waitForFunctions(3000);

      await userRef.delete();
      await productRef.delete();

      await waitForFunctions(3000);

      expect(await env.exportDocuments("users")).toEqual([]);
      expect(await env.exportDocuments("products")).toEqual([]);
    });
  });

  describe("Field Filtering", () => {
    it("should only index specified fields for each collection", async () => {
      const customerData = {
        name: "John Doe",
        email: "john@example.com",
        profile: {
          age: 30,
          location: "New York",
        },
        age: 30,
        phone: "123-456-7890", // This should not be indexed
      };

      const orderData = {
        title: "Sample Order",
        description: "A great order",
        nested_field: {
          category: "electronics",
          tags: ["urgent", "express"],
        },
        price: 99.99,
        category: "electronics", // This should not be indexed
      };

      const customerRef = await env.firestore.collection("customers").add(customerData);
      const orderRef = await env.firestore.collection("orders").add(orderData);
      await env.firestore.collection("orders").add(orderData);

      await waitForFunctions(3000);

      const [customerDoc] = await env.exportDocuments("customers");
      const ordersDocs = await env.exportDocuments("orders");

      expect(customerDoc).not.toHaveProperty("age");
      expect(customerDoc).not.toHaveProperty("phone");
      expect(customerDoc).toStrictEqual({
        id: customerRef.id,
        name: customerData.name,
        email: customerData.email,
        profile: customerData.profile,
      });

      const orderDoc = ordersDocs.find((doc) => doc["id"] === orderRef.id);
      expect(orderDoc).not.toHaveProperty("price");
      expect(orderDoc).not.toHaveProperty("category");
      expect(orderDoc).toStrictEqual({
        id: orderRef.id,
        title: orderData.title,
        description: orderData.description,
        "nested_field.tags": orderData.nested_field.tags,
        "nested_field.category": orderData.nested_field.category,
      });
    });
  });
});

import {afterAll, afterEach, beforeAll, beforeEach, describe, expect, it} from "vitest";
import {handleDocumentWrite, type DocumentChangeLike} from "../../src/indexOnWrite.js";
import {StubTypesense} from "./support/stubTypesense.js";

function snapshot(path: string, exists: boolean, data: Record<string, unknown> = {}): DocumentChangeLike["after"] {
  const id = path.split("/").at(-1) ?? path;
  return {
    exists,
    id,
    ref: {
      path,
      get: () => Promise.resolve({id, data: () => (exists ? data : undefined)}),
    },
  };
}

describe("handleDocumentWrite", () => {
  const typesense = new StubTypesense();

  beforeAll(async () => {
    const port = await typesense.start();
    process.env["FIRESTORE_COLLECTION_PATHS"] = "books";
    process.env["TYPESENSE_COLLECTION_NAMES"] = "books";
    process.env["TYPESENSE_HOSTS"] = "127.0.0.1";
    process.env["TYPESENSE_PORT"] = String(port);
    process.env["TYPESENSE_PROTOCOL"] = "http";
    process.env["TYPESENSE_API_KEY"] = "xyz";
  });

  afterAll(async () => {
    await typesense.stop();
  });

  beforeEach(() => {
    typesense.requests.length = 0;
    typesense.status = 200;
  });

  it("upserts the latest state of a written document", async () => {
    await handleDocumentWrite({before: snapshot("books/doc1", false), after: snapshot("books/doc1", true, {title: "T"})});

    expect(typesense.requests).toStrictEqual([{method: "POST", url: "/collections/books/documents?action=upsert", body: '{"title":"T","id":"doc1"}'}]);
  });

  it("URL-encodes the collection name exactly once", async () => {
    process.env["TYPESENSE_COLLECTION_NAMES"] = "books_firestore/1";
    try {
      await handleDocumentWrite({before: snapshot("books/doc1", false), after: snapshot("books/doc1", true, {title: "T"})});
    } finally {
      process.env["TYPESENSE_COLLECTION_NAMES"] = "books";
    }

    expect(typesense.requests.map(({url}) => url)).toStrictEqual(["/collections/books_firestore%2F1/documents?action=upsert"]);
  });

  it("deletes a removed document", async () => {
    await handleDocumentWrite({before: snapshot("books/doc1", true), after: snapshot("books/doc1", false)});

    expect(typesense.requests.map(({method, url}) => `${method} ${url}`)).toStrictEqual(["DELETE /collections/books/documents/doc1"]);
  });

  it("treats deleting a document that is not in Typesense as success", async () => {
    typesense.status = 404;

    await expect(handleDocumentWrite({before: snapshot("books/doc1", true), after: snapshot("books/doc1", false)})).resolves.toBeUndefined();
  });

  it("still fails on other delete errors", async () => {
    typesense.status = 401;

    await expect(handleDocumentWrite({before: snapshot("books/doc1", true), after: snapshot("books/doc1", false)})).rejects.toThrow("Request failed with HTTP code 401");
  });

  it("ignores documents outside the configured collections", async () => {
    await handleDocumentWrite({before: snapshot("magazines/doc1", false), after: snapshot("magazines/doc1", true)});

    expect(typesense.requests).toStrictEqual([]);
  });

  describe.each([
    {paths: "users,users/{userId}/books", names: "users,books"},
    {paths: "users/{userId}/books,users", names: "books,users"},
  ])("with a collection and its subcollection configured as $paths", ({paths, names}) => {
    beforeEach(() => {
      process.env["FIRESTORE_COLLECTION_PATHS"] = paths;
      process.env["TYPESENSE_COLLECTION_NAMES"] = names;
    });

    afterEach(() => {
      process.env["FIRESTORE_COLLECTION_PATHS"] = "books";
      process.env["TYPESENSE_COLLECTION_NAMES"] = "books";
    });

    it("upserts each document into its own collection", async () => {
      await handleDocumentWrite({before: snapshot("users/u1", false), after: snapshot("users/u1", true, {name: "U"})});
      await handleDocumentWrite({before: snapshot("users/u1/books/b1", false), after: snapshot("users/u1/books/b1", true, {title: "T"})});

      expect(typesense.requests).toStrictEqual([
        {method: "POST", url: "/collections/users/documents?action=upsert", body: '{"name":"U","id":"u1"}'},
        {method: "POST", url: "/collections/books/documents?action=upsert", body: '{"title":"T","id":"b1","userId":"u1"}'},
      ]);
    });

    it("deletes a subcollection document only from its own collection", async () => {
      await handleDocumentWrite({before: snapshot("users/u1/books/b1", true), after: snapshot("users/u1/books/b1", false)});

      expect(typesense.requests.map(({method, url}) => `${method} ${url}`)).toStrictEqual(["DELETE /collections/books/documents/b1"]);
    });

    it("ignores documents in an unconfigured subcollection of a configured collection", async () => {
      await handleDocumentWrite({before: snapshot("users/u1/reviews/r1", false), after: snapshot("users/u1/reviews/r1", true)});
      await handleDocumentWrite({before: snapshot("users/u1/reviews/r1", true), after: snapshot("users/u1/reviews/r1", false)});

      expect(typesense.requests).toStrictEqual([]);
    });
  });
});

